 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The single non-background color forms boundaries; enclosed background
    # components are filled with the output color 4.
    from collections import Counter, deque
    counts = Counter(v for row in grid for v in row)
    wall = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == wall or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            edge = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != wall and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not edge:
                for y, x in comp:
                    out[y][x] = 4
    return out
